\section{Proof of Lemma \ref{lem:One-slot-Mismatching-Bound}~\protect\label{sec:proof_one_slot_mismatching}}
By definition of the phase-alignment vector, $[\mathbf{b}_{*}]_{n}=e^{-j\angle(h_{n})}$
for each $n$. Therefore,
\begin{equation}
\mathbf{b}_{*}^{\top}\mathbf{h}=\sum_{n=1}^{N}e^{-j\angle(h_{n})}h_{n}=\sum_{n=1}^{N}|h_{n}|=\|\mathbf{h}\|_{1}
\end{equation}
which is real and nonnegative, and hence $\big|\mathbf{b}_{*}^{\top}\mathbf{h}\big|=\|\mathbf{h}\|_{1}$.
In this way we have, 
\begin{equation}
|\mathbf{b}_{*}^{\top}\mathbf{h}|^{2}-|\mathbf{b}_{t}^{\top}\mathbf{h}|^{2}=(\|\mathbf{h}\|_{1}-|\mathbf{b}_{t}^{\top}\mathbf{h}|)(\|\mathbf{h}\|_{1}+|\mathbf{b}_{t}^{\top}\mathbf{h}|).\label{eq:app_factorization}
\end{equation}
Since $|\mathbf{b}_{t}^{\top}\mathbf{h}|\le\|\mathbf{h}\|_{1}$, we
have
\begin{equation}
\|\mathbf{h}\|_{1}+|\mathbf{b}_{t}^{\top}\mathbf{h}|\le2\|\mathbf{h}\|_{1}.\label{eq:app_ac_upper}
\end{equation}
It remains to bound the first factor, since we have $\mathbf{b}_{t}^{\top}\mathbf{h}'_{t}=\|\mathbf{h}'_{t}\|_{1}$
which is real and nonnegative. Therefore,
\begin{align}
\|\mathbf{h}\|_{1}-|\mathbf{b}_{t}^{\top}\mathbf{h}| & \le\|\mathbf{h}\|_{1}-\Re\left\{ \mathbf{b}_{t}^{\top}\mathbf{h}\right\} \nonumber 
 & =\|\mathbf{h}\|_{1}-\Re\left\{ \mathbf{b}_{t}^{\top}\mathbf{h}+\mathbf{b}_{t}^{\top}\mathbf{h}'_{t}-\mathbf{b}_{t}^{\top}\mathbf{h}'_{t}\right\} \nonumber 
 & =\|\mathbf{h}\|_{1}-\|\mathbf{h}'_{t}\|_{1}+\Re\left\{ \mathbf{b}_{t}^{\top}(\mathbf{h}'_{t}-\mathbf{h})\right\} \nonumber 
 & \le\big|\|\mathbf{h}\|_{1}-\|\mathbf{h}'_{t}\|_{1}\big|+\left|\Re\left\{ \mathbf{b}_{t}^{\top}(\mathbf{h}'_{t}-\mathbf{h})\right\} \right|\nonumber 
 & \le\|\mathbf{h}-\mathbf{h}'_{t}\|_{1}+\|\mathbf{h}-\mathbf{h}'_{t}\|_{1}=2\|\mathbf{h}-\mathbf{h}'_{t}\|_{1}\label{eq:app_a_minus_c}
\end{align}
where the last inequality uses reverse triangle inequality \cite{triangle_inequality}
and the fact that each entry of $\mathbf{b}_{t}$ has unit modulus
and utilizing Hlder inequality \cite{real_analysis}. Substituting
$(\ref{eq:app_ac_upper})$ and $(\ref{eq:app_a_minus_c})$ into $(\ref{eq:app_factorization})$,
we obtain
\begin{equation}
|\mathbf{b}_{*}^{\top}\mathbf{h}|^{2}-|\mathbf{b}_{t}^{\top}\mathbf{h}|^{2}\le4\|\mathbf{h}\|_{1}\|\mathbf{h}-\mathbf{h}'_{t}\|_{1}.
\end{equation}
Finally, using $\|\mathbf{x}\|_{1}\le\sqrt{N}\|\mathbf{x}\|_{2}$,
we further get
\begin{align}
|\mathbf{b}_{*}^{\top}\mathbf{h}|^{2}-|\mathbf{b}_{t}^{\top}\mathbf{h}|^{2} & \le4(\sqrt{N}\|\mathbf{h}\|_{2})(\sqrt{N}\|\mathbf{h}-\mathbf{h}'_{t}\|_{2}),\nonumber 
 & \le4N\|\mathbf{h}\|_{2}\|\mathbf{h}-\mathbf{h}'_{t}\|_{2},
\end{align}
which proves $(\ref{eq:one_slot_decomposition})$.
\section{Proof of Theorem \ref{thm:Bayesian-regret-decomposition} ~\protect\label{sec:proof_bayesian_regret_decomposition}}
Recall the one-slot instantaneous received-power regret as $\Delta_{t}\triangleq|\mathbf{b}_{*}^{\top}\mathbf{h}|^{2}-|\mathbf{b}_{t}^{\top}\mathbf{h}|^{2}.$
Then $\mathcal{R}_{T}=\sum_{t=1}^{T}\mathbb{E}[\Delta_{t}]$. By Lemma
$\ref{lem:One-slot-Mismatching-Bound}$, we obtain $\Delta_{t}\le4N\|\mathbf{h}\|_{2}\|\mathbf{h}-\mathbf{h}'_{t}\|_{2}.$
Conditioning on $\mathcal{F}_{t-1}$, taking the expectation and applying
Cauchy-Schwarz gives
\begin{align}
\mathbb{E}\left[\Delta_{t}\mid\mathcal{F}_{t-1}\right] & \le4N\Big(\mathbb{E}[\|\mathbf{h}\|_{2}^{2}\mid\mathcal{F}_{t-1}]\Big)^{1/2}\nonumber 
 & \quad\times\Big(\mathbb{E}[\|\mathbf{h}-\mathbf{h}'_{t}\|_{2}^{2}\mid\mathcal{F}_{t-1}]\Big)^{1/2}.\label{eq:app_conditional_cs}
\end{align}
Under the Gaussian posterior update, $\mathbf{h}\mid\mathcal{F}_{t-1}\sim\mathcal{CN}(\bm{\mu}_{t-1},\bm{\Sigma}_{t-1}),$
and sample $\mathbf{h}'_{t}$ is drawn independently from the same
conditional distribution. Therefore, $\mathbf{h}$ and $\mathbf{h}'_{t}$
are conditionally i.i.d. Given $\mathcal{F}_{t-1}$, we have
\begin{equation}
\mathbb{E}\left[\|\mathbf{h}-\mathbf{h}'_{t}\|_{2}^{2}\mid\mathcal{F}_{t-1}\right]=2\text{tr}(\bm{\Sigma}_{t-1}).\label{eq:app_same_posterior}
\end{equation}
Since $\bm{\Sigma}_{t-1}$ is determined by $\mathcal{F}_{t-1}$,
the trace term in $(\ref{eq:app_same_posterior})$ is $\mathcal{F}_{t-1}$-measurable.
Substituting $(\ref{eq:app_same_posterior})$ into $(\ref{eq:app_conditional_cs})$
yields
\begin{equation}
\mathbb{E}\left[\Delta_{t}\mid\mathcal{F}_{t-1}\right]\le4\sqrt{2}N\Big(\mathbb{E}[\|\mathbf{h}\|_{2}^{2}\mid\mathcal{F}_{t-1}]\Big)^{1/2}\bigl(\text{tr}(\bm{\Sigma}_{t-1})\bigr)^{1/2}.
\end{equation}
Taking expectation again and applying Cauchy-Schwarz together with
the tower property gives
\begin{align}
\mathbb{E}[\Delta_{t}] & \le4\sqrt{2}N\mathbb{E}\!\left[\Big(\mathbb{E}[\|\mathbf{h}\|_{2}^{2}\mid\mathcal{F}_{t-1}]\Big)^{1/2}\bigl(\text{tr}(\bm{\Sigma}_{t-1})\bigr)^{1/2}\right]\nonumber 
 & \le4\sqrt{2}N\Big(\mathbb{E}\!\left[\mathbb{E}[\|\mathbf{h}\|_{2}^{2}\mid\mathcal{F}_{t-1}]\right]\Big)^{1/2}\Big(\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]\Big)^{1/2}\nonumber 
 & =4\sqrt{2}NS\sqrt{\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]}.
\end{align}
Summing over $\ensuremath{t=1,2\ldots,T}$ proves $(\ref{eq:Bayesian_regret_decomposition}).$
\section{Proof of Corollary \ref{cor:Sublinear=000020Bayesian=000020regret}
~\protect\label{sec:proof_Sublinear=000020Bayesian=000020regret}}
Under $\mathbf{h}\sim\mathcal{CN}(\mathbf{0},\mathbf{I}_{N})$, the
prior covariance is $\bm{\Sigma}_{0}=\mathbf{I}_{N}$. The sequential
Gaussian observation model implies $\bm{\Sigma}_{t}=(\mathbf{I}_{N}+\sigma^{-2}\mathbf{G}_{t})^{-1}$.
Also, $S^{2}=\mathbb{E}[\|\mathbf{h}\|_{2}^{2}]=N$. We note that
condition (\ref{eq:condition_corollary_3}) is required only for $t\geq\bar{t}_{0}$.
That is because $\mathbf{G}_{t}$ is the sum of $t$ rank-one matrices
and hence cannot be full rank before the number of slots reaches the
channel dimension $N$. We split the regret bound in Theorem \ref{thm:Bayesian-regret-decomposition}
into the contribution of the first $\bar{t}_{0}$ slots and the contribution
of the remaining slots. Specifically, we first consider the contribution
of the first $\bar{t}_{0}$ slots. Since $\bm{\Sigma}_{t}\preceq\mathbf{I}_{N}$
for all $t\geq0$, we have $\text{tr}(\bm{\Sigma}_{t})\leq N$ for
all $t\geq0$. Therefore, 
\begin{equation}
\sum_{t=1}^{\min\{\bar{t}_{0},T\}}\sqrt{\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]}\leq\bar{t}_{0}\sqrt{N}
\end{equation}
According to (\ref{eq:Bayesian_regret_decomposition}), the total
regret accumulated over the first $\bar{t}_{0}$ is upper bounded
by a constant:
\begin{equation}
4\sqrt{2}NS\sum_{t=1}^{\min\{\bar{t}_{0},T\}}\sqrt{\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]}\le4\sqrt{2}NS\bar{t}_{0}\sqrt{N}.\label{eq:finite_initial_phase_bound}
\end{equation}
Then, consider the slot $t\geq\bar{t}_{0}+1$. For such $t$, condition
(\ref{eq:condition_corollary_3}) gives $\lambda_{\min}(\mathbf{G}_{t-1})\ge C((t-1)-\bar{t}_{0}+1)=C(t-\bar{t}_{0})$
almost surely. Hence, $\mathbf{G}_{t-1}\succeq C(t-\bar{t}_{0})\mathbf{I}_{N}.$
Substituting this lower bound into the $\bm{\Sigma}_{t-1}$ gives,
for all $t\geq\bar{t}_{0}+1$,
\begin{equation}
\bm{\Sigma}_{t-1}=(\mathbf{I}_{N}+\sigma^{-2}\mathbf{G}_{t-1})^{-1}\preceq\frac{1}{1+\sigma^{-2}C(t-\bar{t}_{0})}\mathbf{I}_{N}.
\end{equation}
Therefore,
\begin{equation}
\text{tr}(\bm{\Sigma}_{t-1})\le\frac{N}{1+\sigma^{-2}C(t-\bar{t}_{0})},\,\forall t\geq\bar{t}_{0}+1\label{eq:trace_sigma_tminus1_bound_post_t0}
\end{equation}
Since this bound holds almost surely, it also holds after taking expectation:
\begin{equation}
\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]\le\frac{N}{1+\sigma^{-2}C(t-\bar{t}_{0})},\,\forall t\geq\bar{t}_{0}+1.\label{eq:expected_trace_sigma_tminus1_bound_post_t0}
\end{equation}
Substituting (\ref{eq:finite_initial_phase_bound}) and (\ref{eq:expected_trace_sigma_tminus1_bound_post_t0})
into the Bayesian regret decomposition in Theorem \ref{thm:Bayesian-regret-decomposition}
gives
\begin{equation}
\mathcal{R}_{T}\le4\sqrt{2}NS\bar{t}_{0}\sqrt{N}+4\sqrt{2}NS\sum_{t=\bar{t}_{0}+1}^{T}\frac{\sqrt{N}}{\sqrt{1+\sigma^{-2}C(t-\bar{t}_{0})}}.\label{eq:RT_two_parts_cor1}
\end{equation}
Let $a\triangleq\sigma^{-2}C$. Since $x\mapsto(1+ax)^{-1/2}$ is
positive and decreasing on $x>0$, we have
\begin{align}
\sum_{t=\bar{t}_{0}+1}^{T} & \frac{1}{\sqrt{1+\sigma^{-2}C(t-\bar{t}_{0})}}\nonumber 
 & \le1+\int_{0}^{T-\bar{t}_{0}}\frac{dx}{\sqrt{1+\sigma^{-2}Cx}}\nonumber 
 & =1+\frac{2\sigma^{2}}{C}\bigl(\sqrt{1+\sigma^{-2}C(T-\bar{t}_{0})}-1\bigr)\nonumber 
 & =O(\sqrt{T}).\label{eq:integral_test_cor1}
\end{align}
Combining (\ref{eq:RT_two_parts_cor1}) and (\ref{eq:integral_test_cor1})
shows that $\mathcal{R}_{T}=O(\sqrt{T})$ with $T\rightarrow\infty$.
When $t_{0}\leq N$, we have $\bar{t_{0}}=N$. Hence, the regret bound
becomes 
\[
4\sqrt{2}NS\bar{t}_{0}\sqrt{N}=4\sqrt{2}N^{5/2}
\]
which equals $4\sqrt{2}N^{3}$ under the Rayleigh prior $S=\sqrt{N}$.
\section{Proof of Theorem \ref{thm:sublinear=000020comm=000020with=000020channel=000020excitation}~\protect\label{sec:proof=000020sublinear=000020comm=000020with=000020channel=000020excitation} }
We define $\mathbf{S}_{t}\triangleq\sum_{s=1}^{t}\mathbf{Q}_{s}$,
$\mathbf{G}_{t}\triangleq\sum_{s=1}^{t}\mathbf{b}_{s}^{*}\mathbf{b}_{s}^{\top}$
and $\mathbf{X}_{t}\triangleq\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}-\mathbf{Q}_{t}$.
Under the complex-vector convention used in this paper, $\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}$
is Hermitian positive semidefinite because, for any $\mathbf{x}\in\mathbb{C}^{N}$,
$\mathbf{x}^{\mathrm{H}}\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}\mathbf{x}=|\mathbf{b}_{t}^{\top}\mathbf{x}|^{2}\ge0$.
Since $\mathbf{Q}_{t}=\mathbb{E}[\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}\mid\mathcal{F}_{t-1}]$,
the sequence $\{\mathbf{X}_{t}\}_{t\ge1}$ is a Hermitian matrix martingale
difference sequence.
Since each entry of $\mathbf{b}_{t}$ has unit modulus, we have $\|\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}\|=N$.
Moreover, since $\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}\preceq N\mathbf{I}_{N}$,
its conditional expectation also satisfies $\mathbf{Q}_{t}\preceq N\mathbf{I}_{N}$
and hence $||\mathbf{Q}_{t}||\leq N$. Therefore, 
\begin{equation}
\|\mathbf{X}_{t}\|\le\|\mathbf{b}_{t}^{*}\mathbf{b}_{t}^{\top}\|+\|\mathbf{Q}_{t}\|\le2N.
\end{equation}
It follows that
\begin{equation}
\mathbf{X}_{t}^{2}\preceq\|\mathbf{X}_{t}\|^{2}\mathbf{I}_{N}\preceq4N^{2}\mathbf{I}_{N}.
\end{equation}
By the matrix Azuma inequality for self-adjoint matrix martingales
as stated in \cite{tropp2012user}, for any $u>0$,
\begin{equation}
\mathbb{P}\left(\lambda_{\min}\left(\sum_{s=1}^{t}\mathbf{X}_{s}\right)\le-u\right)\le N\exp\left(-\frac{u^{2}}{32N^{2}t}\right).
\end{equation}
Taking $u=(c_{\alpha}/2)t^{\alpha}$ yields
\begin{align}
\mathbb{P} & \left(\lambda_{\min}\left(\sum_{s=1}^{t}\mathbf{X}_{s}\right)\le-\frac{c_{\alpha}}{2}t^{\alpha}\right)\nonumber 
 & \hspace*{1em}\le N\exp\left(-\frac{c_{\alpha}^{2}}{128N^{2}}t^{2\alpha-1}\right).\label{eq:matrix_azuma_poly}
\end{align}
Let $\mathcal{A}_{t}\triangleq\left\{ \lambda_{\min}(\mathbf{S}_{t})\ge c_{\alpha}t^{\alpha}\right\} $
and $\mathcal{B}_{t}\triangleq\left\{ \lambda_{\min}(\mathbf{G}_{t}-\mathbf{S}_{t})\ge-(c_{\alpha}/2)t^{\alpha}\right\} .$
By assumption, $\mathbb{P}(\mathcal{A}_{t}^{c})\le q_{t,\alpha}$.
The concentration bound in $(\ref{eq:matrix_azuma_poly})$ gives
\begin{equation}
\mathbb{P}(\mathcal{B}_{t}^{c})\le N\exp\left(-\frac{c_{\alpha}^{2}}{128N^{2}}t^{2\alpha-1}\right).
\end{equation}
On the event $\mathcal{A}_{t}\cap\mathcal{B}_{t}$, Weyl's inequality
gives
\begin{equation}
\lambda_{\min}(\mathbf{G}_{t})\ge\lambda_{\min}(\mathbf{S}_{t})+\lambda_{\min}(\mathbf{G}_{t}-\mathbf{S}_{t})\ge\frac{c_{\alpha}}{2}t^{\alpha}.
\end{equation}
On this event, the posterior covariance satisfies
\begin{equation}
\text{tr}(\bm{\Sigma}_{t})=\text{tr}\left((\mathbf{I}_{N}+\sigma^{-2}\mathbf{G}_{t})^{-1}\right)\le\frac{N}{1+\frac{c_{\alpha}}{2\sigma^{2}}t^{\alpha}}.
\end{equation}
On the complementary event, we use the trivial bound $\text{tr}(\bm{\Sigma}_{t})\le N$.
Therefore,
\begin{align}
\mathbb{E}[\text{tr}(\bm{\Sigma}_{t})]\le & \frac{N}{1+\frac{c_{\alpha}}{2\sigma^{2}}t^{\alpha}}+N\mathbb{P}(\mathcal{A}_{t}^{c})+N\mathbb{P}(\mathcal{B}_{t}^{c})\nonumber 
\le & \frac{N}{1+\frac{c_{\alpha}}{2\sigma^{2}}t^{\alpha}}+Nq_{t,\alpha}\nonumber 
 & \,+N^{2}\exp\left(-\frac{c_{\alpha}^{2}}{128N^{2}}t^{2\alpha-1}\right).\label{eq:app_trace_bound_poly}
\end{align}
Substituting (\ref{eq:app_trace_bound_poly}) into the Bayesian regret
decomposition in Theorem \ref{thm:Bayesian-regret-decomposition}.
Since $\mathbf{h}\sim\mathcal{CN}(\mathbf{0},\mathbf{I}_{N})$, we
have $S^{2}=\mathbb{E}[||\mathbf{h}||_{2}^{2}]=N$. Moreover, $\bm{\Sigma}_{0}=\mathbf{I}_{N}$,
and hence 
\begin{equation}
\sum_{t=1}^{T}\sqrt{\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]}=\sqrt{N}+\sum_{t=1}^{T-1}\sqrt{\mathbb{E}[\text{tr}(\bm{\Sigma}_{t-1})]}.\label{eq:seperation_trace}
\end{equation}
Substituting (\ref{eq:seperation_trace}) into (\ref{eq:app_trace_bound_poly})
gives 
\begin{align}
\mathcal{R}_{T}=4\sqrt{2} & N^{3/2}\biggl(\sqrt{N}+\sum_{t=1}^{T-1}\Bigl(\frac{N}{1+\frac{c_{\alpha}}{2\sigma^{2}}t^{\alpha}}+Nq_{t,\alpha}\nonumber 
 & ++N^{2}\exp\bigl(-\frac{c_{\alpha}^{2}}{128N^{2}}t^{2\alpha-1}\bigr)\Bigr){}^{1/2}\biggr)
\end{align}
which is the stated finite-horizon bound.
Using $\sqrt{a+b+c}\le\sqrt{a}+\sqrt{b}+\sqrt{c}$, we obtain
\begin{align}
\mathcal{R}_{T} & =O\left(\sum_{t=1}^{T}t^{-\alpha/2}\right)+O\left(\sum_{t=1}^{T}\sqrt{q_{t,\alpha}}\right)\nonumber 
 & \quad+O\left(\sum_{t=1}^{T}\exp\left(-\frac{c_{\alpha}^{2}}{256N^{2}}t^{2\alpha-1}\right)\right).
\end{align}
Since $\alpha>1/2$, the exponential series is summable. Also, $\sum_{t=1}^{T}t^{-\alpha/2}=O(T^{1-\alpha/2})=o(T)$
for any $\alpha>0$. Hence, if $\sum_{t=1}^{T}\sqrt{q_{t,\alpha}}=o(T)$,
then $\mathcal{R}_{T}/T\to0$ as $T\to\infty$. 
\section{Proof of Proposition \ref{prop:unified-dict-vector}~\protect\label{sec:unified-dict-vector-proof}}
For the $n$th RIS element, the steering vector in (\ref{eq:steering=000020vector})
satisfies 
\begin{equation}
[\mathbf{s}(\vartheta,r)]_{n}=\frac{1}{\sqrt{N}}\exp\left\{ j\pi\left[-n\vartheta+\frac{n^{2}d}{2r}(1-\vartheta^{2})\right]\right\} .
\end{equation}
Therefore,
\begin{align}
 & [\mathbf{s}(\vartheta_{\mathrm{b}},r_{\mathrm{b}})\odot\mathbf{s}(\vartheta_{\mathrm{u}},r_{\mathrm{u}})]_{n}\nonumber 
 & =\frac{1}{N}\exp\{j\pi[-n(\vartheta_{\mathrm{b}}+\vartheta_{\mathrm{u}})+\frac{n^{2}d}{2}(\frac{1-\vartheta_{\mathrm{b}}^{2}}{r_{\mathrm{b}}}+\frac{1-\vartheta_{\mathrm{u}}^{2}}{r_{\mathrm{u}}})]\}.\label{eq:proof_unified_product_raw}
\end{align}
Let
\begin{equation}
\nu=\vartheta_{\mathrm{b}}+\vartheta_{\mathrm{u}},\qquad\kappa=\frac{1-\vartheta_{\mathrm{b}}^{2}}{r_{\mathrm{b}}}+\frac{1-\vartheta_{\mathrm{u}}^{2}}{r_{\mathrm{u}}}.\label{eq:kappa_equal}
\end{equation}
The folding rule gives $\vartheta_{{\rm eq}}-\nu\in\{-2,0,2\}$ in
(\ref{eq:folding}). Therefore, for each $n=0,1,\ldots,N-1$, 
\begin{equation}
e^{-j\pi n\vartheta_{{\rm eq}}}=e^{-j\pi n\nu}e^{-j\pi n(\vartheta_{{\rm eq}}-\nu)}=e^{-j\pi n\nu}.\label{eq:var_eq}
\end{equation}
Substituting equivalent representative (\ref{eq:kappa_equal}) and
(\ref{eq:var_eq}) into (\ref{eq:proof_unified_product_raw}) gives
\begin{equation}
[\mathbf{s}(\vartheta_{\mathrm{b}},r_{\mathrm{b}})\odot\mathbf{s}(\vartheta_{\mathrm{u}},r_{\mathrm{u}})]_{n}=\frac{1}{N}\exp\left\{ j\pi\left[-n\vartheta_{{\rm eq}}+\frac{n^{2}d}{2}\kappa\right]\right\} .\label{eq:including_kappa}
\end{equation}
If $\kappa=0$, then (\ref{eq:including_kappa}) equals $1/\sqrt{N}[\mathbf{s}(\vartheta_{\text{eq}},\infty)]_{n}.$
If $\kappa>0$ and $|\vartheta_{\text{eq}}|<1$, then the definition
of $r_{{\rm eq}}$, gives $\kappa=(1-\vartheta_{{\rm eq}}^{2})/r_{{\rm eq}}$.
Therefore,
\begin{align}
[\mathbf{s} & (\vartheta_{\mathrm{b}},r_{\mathrm{b}})\odot\mathbf{s}(\vartheta_{\mathrm{u}},r_{\mathrm{u}})]_{n}\nonumber 
 & =\frac{1}{N}\exp\left\{ j\pi\left[-n\vartheta_{{\rm eq}}+\frac{n^{2}d}{2r_{{\rm eq}}}(1-\vartheta_{{\rm eq}}^{2})\right]\right\} \nonumber 
 & =\frac{1}{\sqrt{N}}[\mathbf{s}(\vartheta_{{\rm eq}},r_{{\rm eq}})]_{n}.
\end{align}
Since this holds for every $n=0,1,\ldots,N-1$, the vector identity
in (\ref{eq:unified_half_wavelength_product}) follows. Applying this
identity to every BS-RIS/RIS-user path pair in (\ref{eq:multipath-equiv-chann})
gives (\ref{eq:unified_sparse_cascaded_channel}).
\section{Proof of Proposition \ref{prop:ring-angule}~\protect\label{sec:proof-ring-ang}}
Let $\omega(\vartheta)\triangleq1-\vartheta^{2}$ and define the normalized
inverse-range variable 
\begin{equation}
\mu\triangleq\frac{\omega(\vartheta)}{r}.\label{eq:definite_mu_r}
\end{equation}
We first analyze the range-boundary rule. Let $\kappa_{\delta}\triangleq4\beta_{\delta}^{2}$.
From (\ref{eq:range-equation-2}), the offset from a dictionary center
to its auxiliary $\delta$-power boundary in the $\mu$-domain is
$\kappa_{\delta}/Z$, which is determined by $\beta_{\delta}$ and
is independent of $\vartheta$. Since two neighboring dictionary atoms
share the same auxiliary $\delta$-power boundary, the center-to-center
inverse-range step is $2\kappa_{\delta}/Z$. Substituting $r=\omega(\vartheta)/\mu$
into the update rule $r^{+}=rZ\omega(\vartheta)/(Z\omega(\vartheta)+2\kappa_{\delta}r),$
we obtain the transformed update in the $\mu$-domain: 
\begin{equation}
\mu^{+}=\mu+\frac{2\kappa_{\delta}}{Z}.\label{eq:mu_plus}
\end{equation}
Thus, the range recursion corresponds to a linear arithmetic progression
in $\mu$, with a constant center-to-center step size $2\kappa_{\delta}/Z$
independent of the angle $\vartheta$.
Consider the range sequence $\{r_{a,q}\}$ at angle $\vartheta_{a}$.
Let $q=0$ denote the far-field center, i.e., $\mu_{a,0}=0$. Based
on (\ref{eq:mu_plus}), the center $q$ is explicitly given by 
\begin{equation}
\mu_{a,q}=q\frac{2\kappa_{\delta}}{Z},\qquad q=0,1,\ldots.\label{eq:mu_a_q}
\end{equation}
Next, consider the range-first sequence given by $r_{m,q}^{\text{RF}}=\omega(\vartheta_{m})r_{a,q}/\omega(\vartheta_{a})$,
with $r_{m,0}^{\text{RF}}=\infty$. For $q\ge1$, applying the definition
(\ref{eq:definite_mu_r}), its inverse variable transforms as 
\begin{equation}
\mu_{m,q}^{\text{RF}}=\frac{\omega(\vartheta_{m})}{r_{m,q}^{\text{RF}}}=\frac{\omega(\vartheta_{m})}{\frac{\omega(\vartheta_{m})}{\omega(\vartheta_{a})}r_{a,q}}=\frac{\omega(\vartheta_{a})}{r_{a,q}}=\mu_{a,q}\label{eq:mu_ring_a_q}
\end{equation}
For $q=0$, the same equality holds by the far-field convention $r=\infty$
and $\mu=0$. Substituting (\ref{eq:mu_a_q}) into (\ref{eq:mu_ring_a_q})
yields $\mu_{m,q}^{\text{RF}}=2q\kappa_{\delta}/Z$.
Now consider the angular-first sequence $\{r_{m,q}^{\text{AF}}\}$
generated at $\vartheta_{m}$, the far-field center has $\mu_{m,0}^{\text{AF}}=0$.
Since the update in the $\mu$-domain is angle independent, the angular-first
atoms satisfy $\mu_{m,q}^{\text{AF}}=2q\kappa_{\delta}/Z$.
Therefore, for every retained index pair $(m,q)$, $\mu_{m,q}^{\text{AF}}=\mu_{m,q}^{\text{RF}}$
and hence $r_{m,q}^{\text{RF}}=r_{m,q}^{\text{AF}}$, and for $q=0,$
the same conclusion holds by the far-field convention $r=\infty$.
It remains to verify that the shared $\delta$-power boundaries are
also preserved. For each retained neighboring pair, the common auxiliary
boundary lies one offset $\kappa_{\delta}/Z$ away from each center
in the $\mu$-domain. Let $\widetilde{r}_{m,q}^{{\rm RF}}$ denote
the boundary between $\ensuremath{r_{m,q}^{{\rm RF}}}$ and $r_{m,q+1}^{{\rm RF}}$,
defined by $\omega(\vartheta_{m})/\widetilde{r}_{m,q}^{\mathrm{RF}}=\mu_{m,q}^{\mathrm{RF}}+\kappa_{\delta}/Z=(2q+1)\kappa_{\delta}/Z$.
Hence, under the Fresnel range-boundary approximation,
\begin{align}
G(\vartheta_{m},\widetilde{r}_{m,q}^{{\rm RF}};\vartheta_{m},r_{m,q}^{{\rm RF}}) & =\delta,
G(\vartheta_{m},\widetilde{r}_{m,q}^{{\rm RF}};\vartheta_{m},r_{m,q+1}^{{\rm RF}}) & =\delta.\nonumber 
\end{align}
Therefore, the range-first construction has the same centers and the
same auxiliary $\delta$-power boundaries as the angular-first construction
for all retained index pairs. This proves the sampling-order equivalence.
