\subsubsection {Classification Error}
As shown in Fig. \ref{fig_5}(a), we first define an intermediate variable $\hat{\bm\theta}_\text{edge}$ to represent the DOA within the classified subregion $\mathcal{C}_p$ having the closest distance to the testing sample $\hat{\bm\theta}$, and use the angle between the directional vectors of these two DOAs to characterize the classification error. Specifically, $\hat{\bm\theta}_\text{edge}$ is represented as
\begin{equation}
\label{edge_model}
\hat{\bm\theta}_\text{edge}=\min \limits_{{\bm\theta}}\{||{\bm\theta}-\hat{\bm\theta}||_F^2,{\bm\theta}\in\mathcal{C}_p\}.
\end{equation}
Therefore, the classification error is defined as
\begin{equation} 
\Delta_{e}= \cos^{-1}( {\hat {\bf v}} \cdot \hat {\bf v}_\text{edge} ) \in [0,\pi],
\end{equation}
where ${\bf \hat v} = (\cos \hat{\theta}^a\sin \hat{\theta}^e,\sin \hat{\theta}^a\sin \hat{\theta}^e, \cos \hat{\theta}^e)^T$ denotes the direction vector corresponding to $\hat{\bm\theta}$ and ${\bf \hat v_\text{edge}} = (\cos \hat{\theta}^a_\text{edge}\sin \hat{\theta}^e_\text{edge},\sin \hat{\theta}^a_\text{edge}\sin \hat{\theta}^e_\text{edge}, \cos \hat{\theta}^e_\text{edge})^T$ denotes the direction vector corresponding to $\hat{\bm\theta}_\text{edge}$. When the classification result is correct, we have $\Delta_{e}=0^{\circ}$. Conversely, a larger classification error indicates that the testing sample is farther from the classified subregion.
Next, we illustrate the expression of \eqref{edge_model} by utilizing the coarse-resolution subregions in the coarse estimation. Suppose that the test sample $\hat{\bm\theta}$ is classified into subregion $\mathcal{G}_g$, $\hat{\bm\theta}_\text{edge}$ can be given by 
\begin{subequations}
\begin{align}
\hat{\theta}_\text{edge}^e&=\begin{cases}g^eE^{e,\text{coarse}}, &\text{if}\ \hat{\theta}^e \in (g^eE^{e,\text{coarse}},\pi], \hat{\theta}^e,&\text{if}\ \hat{\theta}^e\in[\theta_{g}^{e,\text{start}},g^eE^{e,\text{coarse}}], \theta_{g}^{e,\text{start}}, &\text{if}\ \hat{\theta}^e \in[0,\theta_{g}^{e,\text{start}}), \end{cases}
\hat{\theta}_\text{edge}^a&=\begin{cases}g^aE^{a,\text{coarse}}, &\text{if}\ \hat{\theta}^a \in \mathcal{D}_g^{\text{right}}, \hat{\theta}^a,&\text{if}\ \hat{\theta}^a\in[\theta_{a,\text{start}}^{g},g^aE^{a,\text{coarse}}], \theta_{g}^{a,\text{start}}, &\text{if}\ \hat{\theta}^a \in\mathcal{D}_g^{\text{left}}, \end{cases}
\end{align}
\end{subequations}
where $\mathcal{D}_g^{\text{right}}=(g^aE^{a,\text{coarse}},\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2+\pi]$, $\mathcal{D}_g^{\text{left}}=[0,\theta_{g}^{a,\text{start}})\cup(\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2+\pi,2\pi]$ for $\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2 < \pi$ and $\mathcal{D}_g^{\text{right}}=[0,\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2-\pi)\cup (g^aE^{a,\text{coarse}},2\pi]$, $\mathcal{D}_g^{\text{left}}=[\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2-\pi,\theta^{a,\text{start}}_g)$ for $\theta^{a,\text{start}}_g+E^{a,\text{coarse}}/2 > \pi$.
\subsubsection{RMSE}
The RMSE is defined as
\begin{equation}\label{fixed_angle_rmse_define_v3}
\Delta_{\rm E}
=\sqrt{(\Delta\theta^a)^2+(\Delta\theta^e)^2},
\end{equation}
where
\begin{subequations}
\begin{align}
\Delta\theta^a
&=\min\!\left\{|\hat\theta^a-\theta^a|,\,2\pi-|\hat\theta^a-\theta^a|\right\},\label{delta_a_def}
\Delta\theta^e&=\hat\theta^e-\theta^e.\label{delta_e_def}
\end{align}
\end{subequations}
\subsubsection {Peak-to-Average Difference of Angular Spectrum}
We employ the peak-to-average difference to quantify the prominence of the peak in the angular spectrum, which is denoted as
\begin{equation}
\label{DPM_define}
D_\text{PA}=\max\{{\bf f}\}-\frac{\sum_{p=1}^P[{\bf f}]_p}{P}.
\end{equation}
In the fine estimation phase, $D_\text{PA}$ holds two different implications for the testing sample $\hat{\bm\theta}$. 
\begin{itemize}
\item If $\hat{\bm\theta}\in\mathcal{G}_g$, a larger value of $D_{\text{PA}}$ is expected when the peak location of the sub-spectrum aligns with $\hat{\bm\theta}$, this implies that other positions in the angular spectrum hardly surpass the spectral peak, as shown in Fig. \ref{fig_5}(b).
\item If $\tilde{\bm\theta}\notin\mathcal{G}_g$, as shown in Fig. \ref{fig_5}(c)-(d), the signal component outside the subregion $\mathcal{G}_g$ would affect the estimation of DOA within $\mathcal{G}_g$. Specifically, greater spectral fluctuations indicate stronger interference. 
\end{itemize}
Hence, as a result, a higher value of $D_{\text{PA}}$ is expected when the signal DOA is aligned with $\hat{\bm\theta}$, and the value of $D_{\text{PA}}$ should be reduced when the signal is from the outside subregion $\mathcal{G}_g$. 
