\title{Channel-Estimation-Free Beamforming for RIS-Assisted Systems with Limited Feedback}
\author{\IEEEauthorblockN{Hossein Maleki, \IEEEmembership{Graduate Student Member, IEEE} and Hamid Jafarkhani, \IEEEmembership{Fellow, IEEE} \thanks{The authors are with the University of California, Irvine CA, USA. This work was supported in part by the NSF Awards CNS-2229467 and CCF-2328075. Some of the results in this paper were presented at the IEEE International Conference on Communications (ICC-25) \cite{maleki2025lowcomplexity}.}
}
