 \caption{A tree-structured scalar quantizer}
 \label{fig:TSSQ}
\end{figure}
\subsection{Single-Bit Feedback Beamforming}
\label{sec:beamforming}
For fixed phases, the system is the multiple-input single-output (MISO) model $y=\sqrt{P_{\rm T}}\boldsymbol{a}^{\rm H}\boldsymbol{w}s+n$, so we adapt the gradient-sign update of \cite{banister2003simple, spall1992multivariate}. We probe $\boldsymbol{w}\pm\beta\boldsymbol{p}$ with $\boldsymbol{p}\sim\mathcal{CN}(0,2\boldsymbol{I})$ over two slots and keep the unit-norm winner (one feedback bit per iteration). We repeat this procedure for $J$ rounds.
Algorithm~\ref{alg:beamforming} provides the details.
\begin{algorithm}
\small
\SetKw{Initialize}{Initialize: }{}{}
\SetKw{Measure}{Measure: }{}{}
\caption{Single-bit feedback beamforming}\label{alg:beamforming}
\Initialize{$\boldsymbol{w}=\frac{1}{\sqrt{N_{\rm T}}}[1,\dots,1]$; $\beta$; $J$}
\For{$j\leftarrow1$ \KwTo $J$}{
$\boldsymbol{p}\leftarrow\mathcal{CN}_{N_{\rm T}\times1}(0,2\boldsymbol{I})$;
$\boldsymbol{w}_e=\tfrac{\boldsymbol{w}+\beta\boldsymbol{p}}{\|\boldsymbol{w}+\beta\boldsymbol{p}\|}$;
$\boldsymbol{w}_o=\tfrac{\boldsymbol{w}-\beta\boldsymbol{p}}{\|\boldsymbol{w}-\beta\boldsymbol{p}\|}$
transmit $\boldsymbol{w}_{\rm e},\boldsymbol{w}_{\rm o}$; \eIf{$\mathrm{RSS}_{\rm e}>\mathrm{RSS}_{\rm o}$}{$\boldsymbol{w}=\boldsymbol{w}_{\rm e}$}{$\boldsymbol{w}=\boldsymbol{w}_{\rm o}$}}
\end{algorithm}
\section{Non-Asymptotic Phase-Alignment Analysis}
\label{sec:theory}
This section presents the theoretical performance analysis of the deterministic RIS phase-alignment step. The analysis is carried out for a fixed transmit beamformer and for one RIS measurement/update sweep. This setting isolates the passive phase-alignment mechanism and provides the analytical building block for the alternating design. The fully adaptive joint algorithm, in which both the beamformer and RIS phases are updated from past RSS feedback, is evaluated numerically in Section~\ref{Results}.
\subsection{Setting}
For a fixed, deterministic unit-norm $\boldsymbol{w}$, the coefficients $z_n=h_{\rm{r},n}^*\boldsymbol{g}_n^{\rm H}\boldsymbol{w}$ satisfy $z_n=X_nY_n$ with $X_n,Y_n\stackrel{\mathrm{i.i.d.}}{\sim}\mathcal{CN}(0,1)$, independent across $n$ (since $h_{r,n}\sim\mathcal{CN}(0,1)$ and, for unit-norm $\boldsymbol{w}$, $\boldsymbol{g}_n^{\rm H}\boldsymbol{w}\sim\mathcal{CN}(0,1)$).
The RIS phase vector $\boldsymbol{\theta}$ used during a measurement sweep is deterministic or independent of $\{z_n\}$. This holds at initialization, or for one sweep conditioned on a phase vector chosen independently of the current channel.
The above assumptions define the scope of the analysis. During the RIS sweep analyzed here, the transmit beamformer $\boldsymbol{w}$ is fixed, and the probing phase vector $\boldsymbol{\theta}$ is either deterministic or chosen independently of the current channel realization. Under this condition, the cascaded coefficients $\{z_n\}$ remain independent across RIS elements, which is the probabilistic structure used in the proofs.
First, we need to prove a number of lemmas. Let $S=\sum_m z_m e^{j\theta_m}$ and $A_n=S-z_n e^{j\theta_n}$.
\begin{lemma}
\label{lem:tail}
Let $Z=XY$, where $X,Y\sim\mathcal{CN}(0,1)$ are independent. Then, for every $t>0$,
\begin{equation}
\Pr(|Z|\ge t)\le 2e^{-t}.
\end{equation}
\end{lemma}
\begin{proof}
 See Appendix~\ref{App:A}.
\end{proof}
\begin{lemma}
\label{lem:smallball}
Let $W_M=\sum_{m=1}^M Z_m e^{j\phi_m}$, where $Z_m=X_mY_m$, $X_m,Y_m\stackrel{\mathrm{i.i.d.}}{\sim}\mathcal{CN}(0,1)$ are mutually independent, and the phases $\phi_m$ are deterministic. Then, for every $M\ge2$, $u\in\mathbb{C}$, and $r>0$,
\begin{equation}
\label{eqn:smallball}
\Pr\left(|W_M-u|\le r\right)\le \frac{2r^2}{M}.
\end{equation}
\end{lemma}
\begin{proof}
See Appendix~\ref{App:B}.
\end{proof}
The next elementary lemma quantifies how much a planar vector's angle can move under an additive perturbation.
\begin{lemma}
\label{lem:angle}
Let $\boldsymbol q\in\mathbb{R}^2\setminus\{0\}$ and
$\boldsymbol e\in\mathbb{R}^2$ with $\|\boldsymbol e\|<\|\boldsymbol q\|$.
Then,
\begin{equation}
\label{eqn:angle-pert}
\left|\angle(\boldsymbol q+\boldsymbol e)-\angle\boldsymbol q\right|
\le
\arcsin\left(\frac{\|\boldsymbol e\|}{\|\boldsymbol q\|}\right)
\le
\frac{\pi}{2}\frac{\|\boldsymbol e\|}{\|\boldsymbol q\|}.
\end{equation}
\end{lemma}
\begin{proof}
The angle difference is invariant under rotation. Therefore, without loss of generality, we assume that $\boldsymbol q=(a,0)$, where $a=\|\boldsymbol q\|$. Let
$\rho=\|\boldsymbol e\|$. Then, $\boldsymbol q+\boldsymbol e$ lies in the disk
of radius $\rho$ centered at $(a,0)$. Since $\rho<a$, this disk does not contain
the origin.
The largest possible angular deviation from the positive real axis occurs along
a tangent line from the origin to this disk. If $\psi$ denotes this tangent
angle, then the radius to the tangent point is perpendicular to the tangent
line and we have
\begin{equation}
\sin\psi=\frac{\rho}{a}.
\end{equation}
Therefore, every point in the disk has an angular deviation at most
$\psi=\arcsin(\rho/a)$, proving the first inequality. The second inequality follows from the convexity of $\arcsin(t)$ on $[0,1]$. Indeed,
$\arcsin(0)=0$ and $\arcsin(1)=\pi/2$, and since a convex function lies below the
chord that connects two points on its graph, we have
\begin{equation}
\arcsin(t)\le (1-t)\arcsin(0)+t\arcsin(1)
=\frac{\pi}{2}t,\quad 0\le t\le1 .
\end{equation}
\end{proof}
\subsection{Finite-$N$ Aggregate Dominance and Direction Stability}
\begin{theorem}
\label{thm:dominance}
Let $N \ge 2$ and define $c_\delta \triangleq \frac{1}{2}\sqrt{\delta}$.
Then, with probability at least $1-\delta$,
\begin{equation}
\label{eqn:dom1}
 \min_n |A_n|
 \ge
 c_\delta \sqrt{N}
 -
 \log\left(\frac{4N}{\delta}\right),
 \qquad
 \max_n |z_n|
 \le
 \log\left(\frac{4N}{\delta}\right).
\end{equation}
If $c_\delta \sqrt{N}\ge 2\log\left(\frac{4N}{\delta}\right)$, then with probability at least $1-\delta$,
\begin{equation}
 \min_n |A_n|
 \ge
 \frac{c_\delta}{2}\sqrt{N},
 \qquad
 \frac{\min_n |A_n|}{\max_n |z_n|}
 \ge
 \frac{c_\delta \sqrt{N}}
 {2\log\left(4N/\delta\right)}.
\end{equation}
\end{theorem}
\begin{proof}
 See Appendix~\ref{App:C}.
\end{proof}
\begin{theorem}
\label{thm:direction}
Under Theorem~\ref{thm:dominance}, if $c_\delta\sqrt N\ge3\log(4N/\delta)$, then with probability at least $1-\delta$,
\begin{equation}
\label{eqn:dir}
\Gamma_N\triangleq\max_n|\angle S-\angle A_n|\le\frac{4}{c_\delta}\frac{\log(4N/\delta)}{\sqrt N}=O\Bigl(\frac{\log N}{\sqrt N}\Bigr).
\end{equation}
\end{theorem}
\begin{proof}
 See Appendix~\ref{App:D}.
\end{proof}
\subsection{Estimator Stability and One-Sweep Bound}
\begin{theorem}
\label{thm:lipschitz}
Let $\alpha^\star = F(d_1^\star,d_2^\star)$, where $F(d_1,d_2)=\operatorname{atan2}(d_1-2d_2,-d_1)$, and define
\begin{equation}
R^\star
\triangleq
\sqrt{(d_1^\star)^2+(d_1^\star-2d_2^\star)^2}
=
4|A_n|\,|z_n|.
\end{equation}
For measured values $\widehat d_i=d_i^\star+\Delta_i$, define $\widehat\alpha=F(\widehat d_1,\widehat d_2)$. If $|\Delta_1|+|\Delta_2|\le R^\star/4$, then
\begin{equation}
\label{eqn:lip}
|\widehat\alpha-\alpha^\star|
\le
\frac{4}{R^\star}\bigl(|\Delta_1|+|\Delta_2|\bigr).
\end{equation}
Now suppose the measurement errors satisfy the tail bound $\Pr(|\Delta_i|>t)\le 2\exp(-t^2/(2\sigma^2))$ for $i=1,2$ and all $t>0$. Equivalently, the errors are sub-Gaussian with variance proxy $\sigma^2$, meaning that their tails are no heavier than those of a zero-mean Gaussian random variable with variance $\sigma^2$. Then, for any $x\in(0,\pi]$,
\begin{equation}
\Pr\left(|\widehat\alpha-\alpha^\star|>x\right)
\le
4\exp\left(-\frac{x^2(R^\star)^2}{128\sigma^2}\right)
+
4\exp\left(-\frac{(R^\star)^2}{128\sigma^2}\right).
\end{equation}
\end{theorem}
\begin{proof}
 See Appendix~\ref{App:E}.
\end{proof}
\begin{theorem}
\label{thm:onesweep}
Fix $\boldsymbol{w}$ and let $\widehat{\boldsymbol\theta}$ be the RIS phases after one alignment sweep. Define the residual phase error of Element $n$ relative to the common coherent direction $\bar\phi$ by
\begin{equation}
\xi_n
\triangleq
\bigl(\angle z_n+\widehat\theta_n\bigr)-\bar\phi
\pmod{2\pi},
\qquad
\xi_n\in(-\pi,\pi].
\end{equation}
Let
\begin{equation}
\eta_n
\triangleq
\varepsilon_n+\Delta_L+\Gamma_N,
\end{equation}
where $\varepsilon_n$ is the geometric-estimation error, $\Delta_L$ is the quantization error, and $\Gamma_N$ is the reference-direction error. If $|\xi_n|\le \eta_n$ for every $n$, then
\begin{equation}
\label{eqn:onesweep0}
|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|
\ge
\sum_{n=1}^N |z_n|\cos\xi_n .
\end{equation}
Moreover,
\begin{equation}
\label{eqn:onesweep}
|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|
\ge
S^\star(\boldsymbol{w})
-
\frac{1}{2}
\sum_{n=1}^N |z_n|\eta_n^2 .
\end{equation}
\end{theorem}
\begin{proof}
By definition of $\xi_n$, the $n$th aligned contribution can be written as
$z_ne^{j\widehat\theta_n}=|z_n|e^{j(\bar\phi+\xi_n)}$. Therefore,
\begin{equation}
S(\widehat{\boldsymbol\theta},\boldsymbol{w})
=
\sum_{n=1}^N z_ne^{j\widehat\theta_n}
=
e^{j\bar\phi}
\sum_{n=1}^N |z_n|e^{j\xi_n}.
\end{equation}
Since multiplication by $e^{j\bar\phi}$ is a global rotation, it does not change the magnitude. Hence,
\begin{equation}
\begin{aligned}
|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|
=
\left|
\sum_{n=1}^N |z_n|e^{j\xi_n}
\right|
&\ge
\operatorname{Re}
\left\{
\sum_{n=1}^N |z_n|e^{j\xi_n}
\right\}

&=
\sum_{n=1}^N |z_n|\cos\xi_n.
\end{aligned}
\end{equation}
Next, using the inequality $\cos t\ge 1-t^2/2$ for all real $t$, we obtain $\cos\xi_n
\ge
1-\frac{\xi_n^2}{2}$.
Since $|\xi_n|\le \eta_n$, we have $\xi_n^2\le \eta_n^2$, and therefore
\begin{equation}
\cos\xi_n
\ge
1-\frac{\eta_n^2}{2}.
\end{equation}
Substituting this bound into \eqref{eqn:onesweep0} gives
\begin{equation}
\begin{aligned}
|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|
&\ge
\sum_{n=1}^N |z_n|
\left(
1-\frac{\eta_n^2}{2}
\right)

&=
\sum_{n=1}^N |z_n|
-
\frac{1}{2}
\sum_{n=1}^N |z_n|\eta_n^2 .
\end{aligned}
\end{equation}
Finally, since $S^\star(\boldsymbol{w})=\sum_{n=1}^N |z_n|$, we obtain
\begin{equation}
|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|
\ge
S^\star(\boldsymbol{w})
-
\frac{1}{2}
\sum_{n=1}^N |z_n|\eta_n^2 ,
\end{equation}
which proves \eqref{eqn:onesweep}.
\end{proof}
\begin{remark}
Theorem~\ref{thm:onesweep} converts the elementwise phase-error bounds into a received-field guarantee after one alignment sweep. The bound holds on the event where the geometric-estimation, quantization, and reference-direction error bounds all hold, so that $|\xi_n|\le\eta_n=\varepsilon_n+\Delta_L+\Gamma_N$ for every element. On this event, the received magnitude is lower bounded by the ideal coherent sum minus a quadratic penalty in the residual phase-error bounds, showing that small phase errors cause only second-order loss in the received field.
\end{remark}
\subsection{Convergence of the Received-Power Ratio}
\begin{theorem}
\label{thm:ratio}
Fix $\boldsymbol{w}$ and $\delta\in(0,1)$. For each element with
$R_n^\star=4|A_n||z_n|>0$, define the measurement-induced phase-error envelope as
\begin{equation}
\label{eqn:eta-meas}
\eta_n^{\mathrm{meas}}
\triangleq
\begin{cases}
\dfrac{4\bigl(|\Delta_{1,n}|+|\Delta_{2,n}|\bigr)}{R_n^\star},
&
|\Delta_{1,n}|+|\Delta_{2,n}|\le R_n^\star/4,
[1ex]
\pi,
&
\text{otherwise}.
\end{cases}
\end{equation}
For the degenerate case $R_n^\star=0$, set $\eta_n^{\mathrm{meas}}=\pi$.
Let $\mathcal E_{\mathrm{dir}}$ denote the direction-stability event from
Theorem~\ref{thm:direction}. Under the sufficient condition of
Theorem~\ref{thm:direction}, this event holds with probability at least
$1-\delta$ over the channel. On $\mathcal E_{\mathrm{dir}}$, with
$\Delta_L=\pi/2^L$ and $\Gamma_N$ defined in \eqref{eqn:dir}, the normalized
received magnitude satisfies
\begin{equation}
\label{eqn:weighted-gap}
\frac{|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|}
 {S^\star(\boldsymbol{w})}
\ge
1
-
\frac{1}{2S^\star(\boldsymbol{w})}
\sum_{n=1}^N
|z_n|
\bigl(\eta_n^{\mathrm{meas}}+\Delta_L+\Gamma_N\bigr)^2 .
\end{equation}
Consequently, if
\begin{equation}
\label{eqn:weighted-condition}
\frac{\sum_{n=1}^N |z_n|(\eta_n^{\mathrm{meas}})^2}
 {S^\star(\boldsymbol{w})}
\xrightarrow{\mathbb P}
0,
\qquad
\Delta_L\to0,
\qquad
\Gamma_N\to0,
\end{equation}
then
\begin{equation}
\frac{|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|}
 {S^\star(\boldsymbol{w})}
\xrightarrow{\mathbb P}
1,
\end{equation}
and
\begin{equation}
\frac{\rho(\widehat{\boldsymbol\theta},\boldsymbol{w})}
 {\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})}
\xrightarrow{\mathbb P}
1,
\end{equation}
where
$\rho(\widehat{\boldsymbol\theta},\boldsymbol{w})
\triangleq P_{\rm T}|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|^2$
and
$\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})
\triangleq P_{\rm T}(S^\star(\boldsymbol{w}))^2$.
\end{theorem}
\begin{proof}
The residual phase error $\xi_n$ in Theorem~\ref{thm:onesweep} is bounded by three contributions: the measurement-induced geometric-estimation error $|\widehat\alpha_n-\alpha_n^\star|$, the quantization error, and the reference-direction error. The quantization error is at most $\Delta_L=\pi/2^L$, and by Theorem~\ref{thm:direction}, the reference-direction error is at most $\Gamma_N$ on the direction-stability event $\mathcal E_{\mathrm{dir}}$.
For the geometric-estimation error, Theorem~\ref{thm:lipschitz} gives
$|\widehat\alpha_n-\alpha_n^\star|
\le
4(|\Delta_{1,n}|+|\Delta_{2,n}|)/R_n^\star$
whenever $R_n^\star>0$ and
$|\Delta_{1,n}|+|\Delta_{2,n}|\le R_n^\star/4$. By the definition of
$\eta_n^{\mathrm{meas}}$ in \eqref{eqn:eta-meas}, this implies
$|\widehat\alpha_n-\alpha_n^\star|\le \eta_n^{\mathrm{meas}}$ on this event.
Outside this event, or in the degenerate case $R_n^\star=0$, we set
$\eta_n^{\mathrm{meas}}=\pi$, and the trivial bound
$|\widehat\alpha_n-\alpha_n^\star|\le \pi$ holds because phase errors are measured as principal angle differences in $(-\pi,\pi]$. Hence, in all cases,
$|\widehat\alpha_n-\alpha_n^\star|\le \eta_n^{\mathrm{meas}}$.
Therefore, by the triangle inequality, on $\mathcal E_{\mathrm{dir}}$,
\begin{equation}
|\xi_n|
\le
\eta_n^{\mathrm{meas}}+\Delta_L+\Gamma_N .
\end{equation}
Substituting this elementwise bound into Theorem~\ref{thm:onesweep} and dividing by
$S^\star(\boldsymbol{w})=\sum_{n=1}^N |z_n|$ gives
\begin{equation}
\frac{|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|}
 {S^\star(\boldsymbol{w})}
\ge
1
-
\frac{1}{2S^\star(\boldsymbol{w})}
\sum_{n=1}^N
|z_n|
\bigl(\eta_n^{\mathrm{meas}}+\Delta_L+\Gamma_N\bigr)^2 ,
\end{equation}
which proves \eqref{eqn:weighted-gap}.
It remains to prove the convergence statement. Using
$(a+b+c)^2\le 3(a^2+b^2+c^2)$, we obtain
\begin{equation}
\begin{aligned}
\frac{
\sum_{n=1}^N
|z_n|
\bigl(\eta_n^{\mathrm{meas}}+\Delta_L+\Gamma_N\bigr)^2
}
{2S^\star(\boldsymbol{w})}
&\le
\frac{3}{2}
\frac{
\sum_{n=1}^N |z_n|(\eta_n^{\mathrm{meas}})^2
}
{S^\star(\boldsymbol{w})}

&\quad
+
\frac{3}{2}\Delta_L^2
+
\frac{3}{2}\Gamma_N^2 .
\end{aligned}
\end{equation}
Here, we used
$\sum_{n=1}^N |z_n|\Delta_L^2=\Delta_L^2 S^\star(\boldsymbol{w})$
and
$\sum_{n=1}^N |z_n|\Gamma_N^2=\Gamma_N^2 S^\star(\boldsymbol{w})$.
Under \eqref{eqn:weighted-condition}, together with $\Delta_L\to0$ and
$\Gamma_N\to0$, the right-hand side converges to zero in probability. Therefore,
\eqref{eqn:weighted-gap} implies
\begin{equation}
\frac{|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|}
 {S^\star(\boldsymbol{w})}
\xrightarrow{\mathbb P}
1 .
\end{equation}
Finally, since
$\rho(\widehat{\boldsymbol\theta},\boldsymbol{w})
/
\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})
=
\bigl(|S(\widehat{\boldsymbol\theta},\boldsymbol{w})|/S^\star(\boldsymbol{w})\bigr)^2$,
the continuous-mapping gives
\begin{equation}
\frac{\rho(\widehat{\boldsymbol\theta},\boldsymbol{w})}
 {\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})}
\xrightarrow{\mathbb P}
1 .
\end{equation}
This proves the theorem.
\end{proof}
\begin{remark}
The weighted condition in \eqref{eqn:weighted-condition} does not need to be checked directly through the unknown ideal magnitude $S^\star(\boldsymbol{w})$. Since $
S^\star(\boldsymbol{w})=\sum_{n=1}^N |z_n|$, we have
\begin{equation}
\frac{\sum_{n=1}^N |z_n|(\eta_n^{\mathrm{meas}})^2}
 {S^\star(\boldsymbol{w})}
=
\sum_{n=1}^N
\frac{|z_n|}{S^\star(\boldsymbol{w})}
(\eta_n^{\mathrm{meas}})^2
\le
\max_{1\le n\le N}(\eta_n^{\mathrm{meas}})^2 .
\end{equation}
Therefore, the simpler sufficient condition
\begin{equation}
\max_{1\le n\le N}\eta_n^{\mathrm{meas}}
\xrightarrow{\mathbb P}
0
\end{equation}
implies the weighted condition in \eqref{eqn:weighted-condition}. Thus, the theorem can be interpreted as saying that if the worst elementwise measurement-induced phase error, the quantization error, and the reference-direction error all vanish, then the normalized received magnitude and the corresponding received power both converge to their ideal values.
\end{remark}
\begin{remark}
Theorem~\ref{thm:ratio} explains why the noisy-RSS simulations can remain near-optimal even when some weak elements have poor phase estimates. Their loss is weighted by $|z_n|(\eta_n^{\mathrm{meas}})^2$, so they do not dominate the normalized received magnitude. The result is also consistent with single-bit feedback, since $B=1$ is allowed per feedback use. The quantization error decreases through the total refinement depth $L=KB$, giving $\Delta_L=\pi/2^L$.
\end{remark}
\subsection{Finite-Alphabet (Discrete) Phase Shifters}
\label{sec:discrete}
As explained in Section \ref{sec:TSSQ-spec}, a practical RIS element uses a $b$-bit low-resolution phase shifter, allowing it to select one of $2^b$ discrete phase values. Consequently, the residual phase error of Theorem~\ref{thm:onesweep} carries a single deterministic quantization term $\Delta_b$:
\begin{equation}
\label{eqn:xi-matched}
|\xi_n|\;\le\;\eta_n^{\mathrm{meas}}+\Gamma_N+\Delta_b,
\qquad \Delta_b=\frac{\pi}{2^b}.
\end{equation}
\begin{corollary}
\label{cor:discrete}
Let $b\ge2$ and $\xi_{\max}\triangleq\max_n\bigl(\eta_n^{\mathrm{meas}}
+\Gamma_N+\Delta_b\bigr)$. On the direction-stability event of
Theorem~\ref{thm:ratio}, if $\xi_{\max}\le\pi/2$ then
\begin{equation}
\label{eqn:matched-cos2}
\frac{\widehat\rho_{K,b}}{\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})}
\;\ge\;\cos^2(\xi_{\max}).
\end{equation}
In the noiseless, large-array regime
($\max_n\eta_n^{\mathrm{meas}}\to0$, $\Gamma_N\to0$) this becomes
\begin{equation}
\label{eqn:matched-asymp}
\frac{\widehat\rho_{K,b}}{\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})}
\;\ge\;\cos^2\!\Big(\frac{\pi}{2^{b}}\Big),
\qquad
1-\frac{\widehat\rho_{K,b}}{\rho^\star_{\mathrm{RIS}}(\boldsymbol{w})}
\;\le\;\sin^2\!\Big(\frac{\pi}{2^{b}}\Big).
\end{equation}
\end{corollary}
\begin{proof}
Follows directly from the definitions.
\end{proof}
\section{Multi-User RIS}
In this section, we extend the results to the case with $K$ users. Let us denote the channel between RIS and User $k$ by $\boldsymbol{h}_{\rm r}^{(k)}\in\C^{1\times N}$. The RIS applies $\boldsymbol{\Theta}=\mathrm{diag}(e^{j\theta_1},\dots,e^{j\theta_N})$, and the effective channel between base station (BS) and User $k$ is
\begin{equation}
\label{eq:gk}
\boldsymbol{g}_k(\bm\theta)=\boldsymbol{h}_{\rm r}^{(k)}\boldsymbol{\Theta}\boldsymbol{G}\in\C^{1\times N_{\rm T}}.
\end{equation}
The BS uses a precoder $\boldsymbol{W}=[\boldsymbol{w}_1,\dots,\boldsymbol{w}_K]\in\C^{N_{\rm T}\times K}$ with unit-norm columns, $\|\boldsymbol{w}_k\|=1$. With data symbols $s_j$ ($\E|s_j|^2=1$) and noise $n_k\sim\mathcal{CN}(0,\sigma^2)$, User $k$ receives $y_k=\boldsymbol{g}_k\boldsymbol{w}_ks_k+\sum_{j\neq k}\boldsymbol{g}_k\boldsymbol{w}_js_j+n_k$, and we have
\begin{equation}
\label{eq:sinr}
\sinr_k(\bm\theta,\boldsymbol{W})=\frac{|\boldsymbol{g}_k\boldsymbol{w}_k|^2}{\sigma^2+\sum_{j\neq k}|\boldsymbol{g}_k\boldsymbol{w}_j|^2}.
\end{equation}
Let us define $\phi_k\triangleq\log_2(1+\sinr_k)$. For fairness weights $\alpha_k>0$, the weighted objective is
\begin{equation}
\label{eq:Phi}
\Phi_\alpha(\bm\theta,\boldsymbol{W})\triangleq\sum_{k=1}^K\alpha_k\,\phi_k(\bm\theta,\boldsymbol{W}).
\end{equation}
\subsection{A Unified Single-Bit Consensus}
\label{sec:primitive}
The RIS phases and the transmit beamformers are shared resources. A phase
$\theta_n$ affects every effective user channel in \eqref{eq:gk}, while a
precoding vector $\mathbf w_k$ carries User $k$'s signal and simultaneously
creates interference for all users $j\neq k$. Hence, both passive and active
updates should account for their network-wide effect. We use the following common one-bit consensus rule. A shared variable is probed
in two opposite directions; each user reports whether its own SINR improves, and
the BS updates according to a weighted vote. Let $\mathbf x$ denote the variable being updated, either the RIS phase vector
$\bm\theta$ or the precoder $\mathbf W$. Let $\mathcal R$ be the constraint-enforcing map, let $\mathbf d$ be a probe direction, and let
$\beta>0$ be the probe size. The BS forms $\mathbf x^{+}=\mathcal R(\mathbf x+\beta\mathbf d)$ and 
$\mathbf x^{-}=\mathcal R(\mathbf x-\beta\mathbf d)$.
Each user returns the one-bit comparison
\begin{equation}
\label{eq:bit}
b_k
=
\mathbf 1
\left\{
\sinr_k(\mathbf x^{+})>\sinr_k(\mathbf x^{-})
\right\}.
\end{equation}
Equivalently, since $\phi_k=\log_2(1+\sinr_k)$ is increasing in $\sinr_k$,
this bit also indicates whether User $k$'s rate improves. The BS then forms $S=\sum_{k=1}^{K}\alpha_k(2b_k-1)$,
where $\alpha_k\ge0$ is the fairness or priority weight of User $k$, and
updates
\begin{equation}
 \mathbf x
\leftarrow
\mathcal R\left(\mathbf x+\beta\,\operatorname{sgn}_0(S)\mathbf d\right),
\end{equation}
where $\operatorname{sgn}_0(S)=1$ if $S\ge0$ and
$\operatorname{sgn}_0(S)=-1$ otherwise.
The RIS and beamforming updates are two instances of this method. For the RIS phase update, set $\mathbf x=\bm\theta$, $\mathcal R(\bm\theta)=\bm\theta \bmod 2\pi$, and 
$\mathbf d=\mathbf e_n$.
For a selected RIS element $n$, the BS probes $\theta_n^{+}=\theta_n+\beta_\theta$ and $\theta_n^{-}=\theta_n-\beta_\theta$
with all other phases fixed. Users vote and the BS computes $S_n=\sum_{k=1}^{K}\alpha_k(2b_k-1)$,
and updates $\theta_n
\leftarrow
\theta_n+\beta_\theta\,\operatorname{sgn}_0(S_n)
\quad \bmod 2\pi$.
For the beamforming update, set $\mathbf x=\mathbf W=[\mathbf w_1,\ldots,\mathbf w_K]$ and let $\mathcal R$ normalize the updated beamforming column. To update Column $k$, draw
$\mathbf p_k\sim\mathcal{CN}(\mathbf 0,\mathbf I_{N_{\rm T}})$ and define the matrix perturbation $
\boldsymbol{d} = \mathbf P_k
=
\mathbf p_k\mathbf e_k^T
\in\mathbb C^{N_{\rm T}\times K}$.
Equivalently, $\mathbf P_k$ has $\mathbf p_k$ as its $k$-th column and
zeros in all other columns. The BS forms $\mathbf W^{+}
=
\mathcal R(\mathbf W+\beta_w\mathbf P_k)$ and
$\mathbf W^{-}
=
\mathcal R(\mathbf W-\beta_w\mathbf P_k)$
so that only the $k$-th beamforming column is perturbed. In column notation, $\mathbf w_k^{+}
=
\mathrm{normalize}(\mathbf w_k+\beta_w\mathbf p_k)$ and
$\mathbf w_k^{-}
=
\mathrm{normalize}(\mathbf w_k-\beta_w\mathbf p_k)$,
while all other columns remain fixed. Because
$\mathbf w_k$ not only increases the desired signal of User $k$, but also changes the
interference experienced by users $j\neq k$, all users need to vote. The BS computes $S_k=\sum_{j=1}^{K}\alpha_j(2b_j-1)$
and sets
\begin{equation}
 \mathbf W
\leftarrow
\begin{cases}
\mathbf W^{+}, & S_k\ge0,
\mathbf W^{-}, & S_k<0.
\end{cases}
\end{equation}
Updating one beamforming column at a time makes the consensus decision
interpretable: users vote on the network-wide effect of a single shared
degree of freedom. A global perturbation of all columns would instead mix the
effects of desired-signal changes and interference changes across all users,
making one-bit feedback much less informative.
\begin{remark}
\label{rem:selfish}
A selfish column update is obtained by replacing the consensus weights with the
degenerate vector $\bm\alpha=\mathbf e_k$. Then, only User $k$'s vote affects
the update of $\mathbf w_k$. This ignores the interference that
$\mathbf w_k$ causes to the other users. The consensus rule retains the same
one-bit feedback structure, but allows users harmed by the perturbation to vote
against it.
\end{remark}
\subsection{One-Bit Vote Consistency} In this subsection, we want to show that a single sign bit, taken with a small symmetric probe, reveals the sign of a directional derivative.
\begin{lemma}
\label{lem:vote}
Fix $(\bm\theta,\mathbf{W})$, an element $n$, and a user $k$, and let $g\triangleq\partial\sinr_k/\partial\theta_n$. The difference $D_k(\beta)\triangleq\sinr_k(\bm\theta+\beta\mathbf e_n,\mathbf W)-\sinr_k(\bm\theta-\beta\mathbf e_n,\mathbf W)$ satisfies
\begin{equation}
\label{eq:Dexp}
D_k(\beta)=2\beta\,g+O(\beta^3)\qquad(\beta\to0).
\end{equation}
Consequently, if $g\neq0$, there is $\beta_0>0$ such that for all $0<\beta_\theta<\beta_0$, the feed-back bit obeys
\begin{equation}
 2b_k-1=\sign(g)=\sign\Bigl(\frac{\partial\phi_k}{\partial\theta_n}\Bigr).
\end{equation}
\end{lemma}
\begin{proof}
Let $f(\beta)=\sinr_k(\bm\theta+\beta\mathbf e_n,\mathbf W)$. Then, $D_k(\beta)=f(\beta)-f(-\beta)$ is an odd function of $\beta$, so its Maclaurin expansion contains only odd powers: 
\begin{equation}
 D_k(\beta)=2f'(0)\beta+\tfrac{2}{3!}f'''(0)\beta^3+\cdots=2\beta g+O(\beta^3),
\end{equation}
 giving \eqref{eq:Dexp}. If $g\neq0$, then $D_k(\beta)=2\beta g\,(1+O(\beta^2))$, so there is $\beta_0>0$ with $\sign(D_k(\beta))=\sign(g)$ for all $0<\beta<\beta_0$. The bit \eqref{eq:bit} is $b_k=\mathbf 1\{D_k>0\}$, hence $2b_k-1=\sign(g)$. Finally, $\phi_k=\log_2(1+\sinr_k)$ is strictly increasing in $\sinr_k$, so $\partial\phi_k/\partial\theta_n=g/((1+\sinr_k)\ln2)$ has the same sign as $g$.
\end{proof}
\begin{lemma}
\label{lem:spsa}
Equip $\mathbb C^{N_{\rm T}\times K}$ with the real inner product
\begin{equation}
\label{eq:realip}
\langle \mathbf A,\mathbf B\rangle_{\mathbb R}
\triangleq
\Re\operatorname{tr}(\mathbf A^{\mathsf H}\mathbf B).
\end{equation}
Let
\[
\nabla_{\mathbf W}\sinr_k
\triangleq
2\frac{\partial \sinr_k}{\partial \mathbf W^*}
\]
denote the Wirtinger conjugate gradient, so that the directional derivative of
$\sinr_k$ along a complex perturbation $\mathbf P$ is
\begin{equation}
\label{eq:dirderiv}
\left.
\frac{d}{d\beta}
\right|_{\beta=0}
\sinr_k(\bm\theta,\mathbf W+\beta\mathbf P)
=
\left\langle
\nabla_{\mathbf W}\sinr_k,\mathbf P
\right\rangle_{\mathbb R}.
\end{equation}
Fix $(\bm\theta,\mathbf W)$ and a perturbation direction $\mathbf P$. Define
the SINR difference
\begin{equation}
 D_k^W(\beta)
\triangleq
\sinr_k(\bm\theta,\mathbf W+\beta\mathbf P)
-
\sinr_k(\bm\theta,\mathbf W-\beta\mathbf P).
\end{equation}
If $\sinr_k$ is three times continuously differentiable in a neighborhood of
$\mathbf W$, then
\begin{equation}
\label{eq:spsa}
D_k^W(\beta)
=
2\beta
\left\langle
\nabla_{\mathbf W}\sinr_k,\mathbf P
\right\rangle_{\mathbb R}
+
O(\beta^3).
\end{equation}
Consequently, whenever $\beta$ is sufficiently small and
$
\left\langle
\nabla_{\mathbf W}\sinr_k,\mathbf P
\right\rangle_{\mathbb R}
\neq 0$,
the comparison bit $\mathbf 1\{D_k^W(\beta)>0\}$
reveals the sign of the directional derivative of $\sinr_k$ along
$\mathbf P$.
\end{lemma}
\begin{proof}
Let $f(\beta)
=
\sinr_k(\bm\theta,\mathbf W+\beta\mathbf P)$.
By the smoothness assumption, $f$ admits a Taylor expansion around $\beta=0$. Its first derivative is
$
f'(0)
=
\left\langle
\nabla_{\mathbf W}\sinr_k,\mathbf P
\right\rangle_{\mathbb R},
$
by \eqref{eq:dirderiv}. Following the proof of Lemma~\ref{lem:vote},
\begin{equation}
\label{eq:two_sided_bf_difference}
D_k^W(\beta)
=
f(\beta)-f(-\beta)
=
2\beta f'(0)+O(\beta^3).
\end{equation}
Substituting the expression for $f'(0)$ yields \eqref{eq:spsa}. If
$f'(0)\neq 0$, then for sufficiently small $\beta$, the linear term
dominates the remainder $O(\beta^3)$, and
\[
\sign D_k^W(\beta)
=
\sign f'(0)
=
\sign
\left\langle
\nabla_{\mathbf W}\sinr_k,\mathbf P
\right\rangle_{\mathbb R}.
\]
\end{proof}
The previous two lemmas provide the local meaning of the one-bit feedback. For a sufficiently small symmetric probe, the bit returned by User $k$ indicates whether that user prefers the positive or negative direction, to the first order. The feedback reveals the sign of each user's local change, but not its magnitude. Therefore, in the general interference-limited multi-user setting, the proposed rule can be interpreted as a coarse one-bit approximation to the ascent direction of the weighted performance objective $\Phi_\alpha$. Since each user reports only a binary comparison, the BS does not observe the exact directional derivatives $\partial_{\mathbf d}\phi_k$ or their magnitudes. Instead, it observes their signs through the local probe. The weighted-majority score therefore acts as a sign-only surrogate for the true weighted directional derivative
\begin{equation}
\label{eq:true_weighted_directional_derivative}
\partial_{\mathbf d}\Phi_\alpha
=
\sum_k \alpha_k \partial_{\mathbf d}\phi_k .
\end{equation}
When the users' local directional preferences are broadly aligned, or when the majority direction also captures the dominant weighted derivative contribution, this surrogate selects the same first-order direction as the weighted-sum objective. Thus, the consensus step provides a low-overhead approximation of gradient-based coordination using only single-bit user feedback.
In the single-user case, this approximation becomes exact at the sign level. When $K=1$, the weighted-majority score reduces to the single user's bit, and Lemmas~\ref{lem:vote} and~\ref{lem:spsa} show that the update follows the local ascent direction for sufficiently small probes. Hence, the proposed primitive reduces to the standard single-user single-bit adaptation rule for $K=1$, while for multiple users, it provides a sign-based scalable approximation to the coordinated weighted-gradient adaptation.
\section{Simulation Results}
\label{Results}
For simulations, the channels are i.i.d. Rayleigh, i.e., the entries of $\boldsymbol{G}$ and $\boldsymbol{h}_{\rm r}$, are i.i.d. $\mathcal{CN}(0,1)$. The initial RIS phases are $U(-\pi,\pi]$, $\boldsymbol{w}=\frac{1}{\sqrt{N_{\rm T}}}[1,\dots,1]$, TSSQ uses $B=1$ bit/use and $R=6$ (so $L=6$ bits/element, i.e., 6-level TSSQ), and the beamforming step is $\beta=0.01$ ($N_{\rm T}=4$) or $0.003$ ($N_{\rm T}=16$). Throughout this section, "benchmark" denotes the AO full-CSI method of Section~\ref{SysMod}.
Fig.~\ref{fig:convergence} shows convergence results for a choice of transmit antennas and RIS elements for one user. To place our method in context, we compare it with two families of channel-quantization baselines. The first baseline applies a scalar quantizer (SQ), quantizing each channel coefficient independently. We consider resolutions of $1$, $2$, $3$, and $4$ bits per number, with quantizer levels optimized through the Lloyd algorithm~\cite{gray1998quantization}. Since the system has $(N_{\rm T}+1)N$ complex channels, equivalently $2(N_{\rm T}+1)N$ real numbers, the feedback cost grows quickly. In the setting of Fig.~\ref{fig:convergence}, for example, a $2$-bit SQ must encode $10000$ numbers, amounting to $20000$ bits. Our TSSQ-based algorithm reaches comparable performance in only $3842$ time slots, which corresponds to fewer than $3842$ feedback bits, as the beamforming stage transmits one bit every two slots. The second baseline is a random vector quantizer (RVQ)~\cite{gray1998quantization}. RVQ outperforms SQ when the vectors are low-dimensional, but it becomes difficult to apply as the dimension grows. We therefore quantize the rows of $\mathbf{G}$ directly and split the channel vector $\mathbf{h}_{\rm r}$ into subvectors of length $4$. For each vector, $B_1$ bits encode its direction and $B_2$ bits its magnitude. Because the magnitude is relatively easy to represent, it suffices to use $B_2=2$ bits. As shown in Fig.~\ref{fig:convergence}, our approach outperforms both the SQ and RVQ baselines. Also, it is important to note that we assumed perfect channel estimation for SQ and RVQ; otherwise, their performance would degrade more.
