\section{Proof of Lemma~\ref{lem:tail}}
\label{App:A}
Let $R_1=|X|$ and $R_2=|Y|$. Since $X,Y\sim\mathcal{CN}(0,1)$, the squared magnitudes $R_1^2$ and $R_2^2$ are independent exponential random variables with unit mean. Hence, for every $u\ge0$,
\begin{equation}
\Pr(R_i\ge u)=\Pr(R_i^2\ge u^2)=e^{-u^2},\qquad i=1,2.
\end{equation}
Now, fix $t>0$. If $R_1R_2\ge t$, then both $R_1$ and $R_2$ cannot be smaller than $\sqrt t$; otherwise, $R_1<\sqrt t$ and $R_2<\sqrt t$ would imply $R_1R_2<t$. Therefore,
\begin{equation}
\{R_1R_2\ge t\}
\subseteq
\{R_1\ge\sqrt t\}\cup\{R_2\ge\sqrt t\}.
\end{equation}
Using the union bound and the Rayleigh tail above,
\begin{align}
\Pr(|Z|\ge t)
&=\Pr(R_1R_2\ge t) \nonumber
&\le \Pr(R_1\ge\sqrt t)+\Pr(R_2\ge\sqrt t) \nonumber
&=2e^{-t}.
\end{align}
This proves the lemma.
\section{Proof of Lemma~\ref{lem:smallball}}
\label{App:B}
For $t\in\mathbb{C}$, define the two-dimensional characteristic function
\begin{equation}
\varphi_Z(t)=\mathbb{E}\left[e^{j\mathrm{Re}(\bar t Z)}\right].
\end{equation}
Conditioned on $X$, the product $Z=XY$ is complex Gaussian with distribution
$\mathcal{CN}(0,|X|^2)$. Write $t=t_{\mathrm r}+jt_{\mathrm i}$ and
$Z=Z_{\mathrm r}+jZ_{\mathrm i}$. Then, conditioned on $X$, the real and
imaginary parts $Z_{\mathrm r}$ and $Z_{\mathrm i}$ are independent
$\mathcal{N}(0,|X|^2/2)$ random variables, and
\begin{equation}
\mathrm{Re}(\bar t Z)=t_{\mathrm r}Z_{\mathrm r}+t_{\mathrm i}Z_{\mathrm i}.
\end{equation}
Using the characteristic function of a real Gaussian random variable,
\begin{align}
\mathbb{E}\left[e^{j\mathrm{Re}(\bar t Z)}\mid X\right]
&=
\exp\left(-\frac{|X|^2t_{\mathrm r}^2}{4}\right)
\exp\left(-\frac{|X|^2t_{\mathrm i}^2}{4}\right) \nonumber
&=
\exp\left(-\frac{|X|^2|t|^2}{4}\right).
\end{align}
Finally, since $|X|^2\sim\mathrm{Exp}(1)$,
\begin{align}
\varphi_Z(t)
&=
\int_0^\infty
\exp\left(-\frac{x|t|^2}{4}\right)e^{-x}\,\mathrm{d}x \nonumber
&=
\int_0^\infty
\exp\left[-x\left(1+\frac{|t|^2}{4}\right)\right]\,\mathrm{d}x \nonumber
&=
\frac{1}{1+|t|^2/4}.
\end{align}
Since $Z_m$ is circularly symmetric, multiplying it by the deterministic phase
$e^{j\phi_m}$ does not change its distribution. Hence,
$W_M\stackrel{d}{=}\sum_{m=1}^M Z_m$. Define the normalized sum
$U_M=W_M/\sqrt M$. By independence,
\begin{equation}
\varphi_{U_M}(t)
=
\left(\varphi_Z\left(\frac{t}{\sqrt M}\right)\right)^M
=
\left(1+\frac{|t|^2}{4M}\right)^{-M}.
\end{equation}
For $M\ge2$, this characteristic function is integrable over $\mathbb{R}^2$.
Therefore, by Fourier inversion, $U_M$ has a bounded continuous density
$f_{U_M}$, and
\begin{equation}
\|f_{U_M}\|_\infty
\le
\frac{1}{(2\pi)^2}
\int_{\mathbb{R}^2}
\left(1+\frac{|t|^2}{4M}\right)^{-M}\mathrm{d}t,
\end{equation}
where $\|f\|_\infty=\sup_{x\in\mathbb{R}^2}|f(x)|$.
Using polar coordinates, $t=\rho(\cos\psi,\sin\psi)$, we obtain
\begin{align}
\int_{\mathbb{R}^2}
\left(1+\frac{|t|^2}{4M}\right)^{-M}dt
&=
2\pi\int_0^\infty
\rho\left(1+\frac{\rho^2}{4M}\right)^{-M}d\rho .
\end{align}
Now, we set
\begin{equation}
s=1+\frac{\rho^2}{4M},
\qquad
ds=\frac{\rho}{2M}\,d\rho .
\end{equation}
Then
\begin{align}
2\pi\int_0^\infty
\rho\left(1+\frac{\rho^2}{4M}\right)^{-M}d\rho
&=
4\pi M\int_1^\infty s^{-M}ds \nonumber
&=
\frac{4\pi M}{M-1},
\end{align}
where the last equality holds for $M\ge2$. Therefore,
\begin{align}
\|f_{U_M}\|_\infty
&\le
\frac{1}{(2\pi)^2}\cdot\frac{4\pi M}{M-1} \nonumber
&=
\frac{M}{\pi(M-1)}
\le
\frac{2}{\pi},
\qquad M\ge2.
\end{align}
Finally, fix any $u\in\mathbb{C}$ and $r>0$. Since $U_M=W_M/\sqrt M$,
\begin{align}
\Pr(|W_M-u|\le r)
&=
\Pr\left(\left|U_M-\frac{u}{\sqrt M}\right|
\le
\frac{r}{\sqrt M}\right).
\end{align}
The event on the right is a disk in $\mathbb{R}^2$ with radius $r/\sqrt M$ and area
$\pi r^2/M$. Hence, using the density bound,
\begin{align}
\Pr(|W_M-u|\le r)
&\le
\|f_{U_M}\|_\infty
\frac{\pi r^2}{M} \nonumber
&\le
\frac{2}{\pi}\cdot\frac{\pi r^2}{M}
=
\frac{2r^2}{M}.
\end{align}
This proves the claim.
\section{Proof of Theorem~\ref{thm:dominance}}
\label{App:C}
For every $n$, the reverse triangle inequality applied to $A_n=S-z_ne^{j\theta_n}$ and $|z_ne^{j\theta_n}|=|z_n|$ gives $|A_n|\ge|S|-|z_n|\ge|S|-\max_k|z_k|$. Taking the minimum over $n$,
\begin{equation}
\label{eqn:dom-reduction}
\min_{1\le n\le N}|A_n|\ \ge\ |S|-\max_{1\le n\le N}|z_n|.
\end{equation}
 Applying Lemma~\ref{lem:smallball} with $M=N$, $u=0$, $r=c_\delta\sqrt N$, we get
\begin{equation}
 \Pr\bigl(|S|\le c_\delta\sqrt N\bigr)\le \frac{2(c_\delta\sqrt N)^2}{N}=2c_\delta^2=2\cdot\tfrac{\delta}{4}=\tfrac{\delta}{2},
\end{equation}
for $c_\delta=\tfrac12\sqrt\delta$. Hence, the event $\mathcal{E}_1=\{|S|\ge c_\delta\sqrt N\}$ has $\Pr(\mathcal{E}_1)\ge1-\delta/2$.
By Lemma~\ref{lem:tail}, $\Pr(|z_n|\ge t)\le2e^{-t}$ for each $n$. The union bound gives $\Pr(\max_n|z_n|\ge t)\le 2Ne^{-t}$. Setting $t=\log(4N/\delta)$ results in $2Ne^{-t}=2N\cdot\tfrac{\delta}{4N}=\tfrac{\delta}{2}$, so the event $\mathcal{E}_2=\{\max_n|z_n|\le\log(4N/\delta)\}$ has $\Pr(\mathcal{E}_2)\ge1-\delta/2$. By the union bound $\Pr(\mathcal{E}_1\cap\mathcal{E}_2)\ge1-\delta$. On $\mathcal{E}_1\cap\mathcal{E}_2$, \eqref{eqn:dom-reduction} gives $\min_n|A_n|\ge c_\delta\sqrt N-\log(4N/\delta)$ and the second inequality of \eqref{eqn:dom1} is exactly $\mathcal{E}_2$. If $c_\delta\sqrt N\ge2\log(4N/\delta)$, on the event $\mathcal{E}_1\cap\mathcal{E}_2$, we will have $\min_n|A_n|\ge c_\delta\sqrt N-\tfrac12 c_\delta\sqrt N=\tfrac{c_\delta}{2}\sqrt N$. Dividing by $\max_n|z_n|\le\log(4N/\delta)$ gives $\frac{\min_n |A_n|}{\max_n |z_n|}
 \ge
 \frac{c_\delta \sqrt{N}}
 {2\log\left(4N/\delta\right)}$.
\section{Proof of Theorem~\ref{thm:direction}}
\label{App:D}
Fix $n$ and consider the event $\mathcal{E}_1 \cap \mathcal{E}_2$ from Theorem~\ref{thm:dominance}, which occurs with probability at least $1-\delta$. Identify complex numbers with vectors in $\mathbb{R}^2$ and write $S = A_n + \boldsymbol{e}_n$, where $\boldsymbol{e}_n = z_n e^{j\theta_n}$. Then, we have $\|\boldsymbol{e}_n\| = |z_n|$ and $\|A_n\| = |A_n|$.
If $c_\delta \sqrt{N} \ge 3\log(4N/\delta)$, Theorem~\ref{thm:dominance} gives
\begin{align}
\frac{|z_n|}{|A_n|}
\le
\frac{\log(4N/\delta)}
 {c_\delta \sqrt{N} - \log(4N/\delta)}
&\le
\frac{\log(4N/\delta)}
 {3\log(4N/\delta) - \log(4N/\delta)} \nonumber
&=
\frac{1}{2}.
\end{align}
Therefore, $\|\boldsymbol{e}_n\| < \|A_n\|$ and applying Lemma~\ref{lem:angle} with $\boldsymbol{q}=A_n$ results in
\begin{equation}
|\angle S - \angle A_n|
\le
\arcsin\left(\frac{|z_n|}{|A_n|}\right)
\le
\frac{\pi}{2}\frac{|z_n|}{|A_n|}.
\end{equation}
Moreover, $c_\delta\sqrt N\ge3\log(4N/\delta)$ gives $|A_n|\ge c_\delta\sqrt N-\log(4N/\delta)\ge\tfrac{2}{3}c_\delta\sqrt N$, hence $|A_n|\ge\tfrac{c_\delta}{2}\sqrt N$, and with $|z_n|\le\log(4N/\delta)$,
\[
|\angle S-\angle A_n|\le\frac{\pi}{2}\cdot\frac{\log(4N/\delta)}{(c_\delta/2)\sqrt N}
=\frac{\pi}{c_\delta}\frac{\log(4N/\delta)}{\sqrt N}
\le\frac{4}{c_\delta}\frac{\log(4N/\delta)}{\sqrt N}.
\]
Taking the maximum over $n$ (the bound is uniform in $n$ on the same event) proves \eqref{eqn:dir}.
\section{Proof of Theorem~\ref{thm:lipschitz}}
\label{App:E}
Define $\boldsymbol{q}(d_1,d_2)=(-d_1,\,d_1-2d_2)\in\mathbb{R}^2$. Since $\operatorname{atan2}(y,x)$ is the angle of the vector $(x,y)$, we have $F(d_1,d_2)=\angle\boldsymbol{q}(d_1,d_2)$, and $\|\boldsymbol{q}^\star\|=\sqrt{(d_1^\star)^2+(d_1^\star-2d_2^\star)^2}=R^\star$. (The identity $R^\star=4|A_n||z_n|$ holds because, with $a=|A_n|$, $b=|z_n|$ and $\alpha$ the angle of element $n$ relative to $A_n$, the law of cosines gives $d_1^\star=-4ab\cos\alpha$ and $d_1^\star-2d_2^\star=4ab\sin\alpha$, so $\boldsymbol{q}^\star=4ab(\cos\alpha,\sin\alpha)$, where $\|\boldsymbol{q}^\star\|=4ab$ and $\angle\boldsymbol{q}^\star=\alpha=\alpha^\star$.) The measurement perturbation is $\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star=(-\Delta_1,\ \Delta_1-2\Delta_2)$, and by $\sqrt{p^2+q^2}\le|p|+|q|$,
\begin{align}
\label{eqn:e-bound}
\|\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star\|=\sqrt{\Delta_1^2+(\Delta_1-2\Delta_2)^2}&\le|\Delta_1|+|\Delta_1-2\Delta_2|\nonumber  &\le2(|\Delta_1|+|\Delta_2|).
\end{align}
The assumption $|\Delta_1|+|\Delta_2|\le R^\star/4$ then gives $\|\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star\|\le R^\star/2<\|\boldsymbol{q}^\star\|$. Therefore, Lemma~\ref{lem:angle} (with $\boldsymbol{q}=\boldsymbol{q}^\star$, $\boldsymbol{e}=\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star$) results in
\begin{align}
\label{eqn:est-arcsin}
|\widehat\alpha-\alpha^\star|&\le\arcsin\Bigl(\frac{\|\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star\|}{R^\star}\Bigr)\le\frac{\pi}{2}\frac{\|\widehat{\boldsymbol{q}}-\boldsymbol{q}^\star\|}{R^\star}\nonumber  &\le\frac{\pi(|\Delta_1|+|\Delta_2|)}{R^\star}\le\frac{4(|\Delta_1|+|\Delta_2|)}{R^\star},
\end{align}
which is the same as \eqref{eqn:lip}.
To prove the second part, fix any $x\in(0,\pi]$ and define
$D=|\Delta_1|+|\Delta_2|$ and $H=\{D\le R^\star/4\}$. Then,
\[
\{|\widehat\alpha-\alpha^\star|>x\}
=
\left(\{|\widehat\alpha-\alpha^\star|>x\}\cap H\right)
\cup
\left(\{|\widehat\alpha-\alpha^\star|>x\}\cap H^c\right),
\]
so we can bound the two cases separately. From \eqref{eqn:lip},
\begin{equation}
\begin{aligned}
\left\{|\widehat\alpha-\alpha^\star|>x\right\}
\subseteq
&
\underbrace{
\left\{
D>\frac{xR^\star}{4}
\right\}
}_{\text{small-perturbation region}}
\cup
\underbrace{
\left\{
D>\frac{R^\star}{4}
\right\}
}_{\text{escape event}} .
\end{aligned}
\end{equation}
On $H$, \eqref{eqn:lip} gives $|\widehat\alpha-\alpha^\star|\le 4D/R^\star$, so $|\widehat\alpha-\alpha^\star|>x$ implies $D>xR^\star/4$. On $H^c$, we directly have $D>R^\star/4$, which is the escape event.
Using $\{|a|+|b|>u\}\subseteq\{|a|>u/2\}\cup\{|b|>u/2\}$ and the tail bound $\Pr(|\Delta_i|>u)\le 2\exp(-u^2/(2\sigma^2))$, we obtain
\begin{equation}
\begin{aligned}
\Pr\left(
|\Delta_1|+|\Delta_2|>\frac{xR^\star}{4}
\right)
&\le
4\exp\left(
-\frac{(xR^\star/8)^2}{2\sigma^2}
\right)

&=
4\exp\left(
-\frac{x^2(R^\star)^2}{128\sigma^2}
\right).
\end{aligned}
\end{equation}
Similarly,
\begin{equation}
\Pr\left(
|\Delta_1|+|\Delta_2|>\frac{R^\star}{4}
\right)
\le
4\exp\left(
-\frac{(R^\star)^2}{128\sigma^2}
\right).
\end{equation}
Adding the two bounds gives
\begin{equation}
\Pr\left(|\widehat\alpha-\alpha^\star|>x\right)
\le
4\exp\left(
-\frac{x^2(R^\star)^2}{128\sigma^2}
\right)
+
4\exp\left(
-\frac{(R^\star)^2}{128\sigma^2}
\right),
\end{equation}
which proves the claim.
