\caption{GLRT overlap validation for a one-target/one-victim ULA setting with target angle $\theta_0=0^\circ$, victim angle $\theta_1=18^\circ$, $N_{\mathrm{tx}}=8$, and $T=16$. The two model curves correspond to the large-matrix overlap approximation and its first-order expansion in \eqref{eq:lm_eta}.}
\label{fig:lm_eta_validation}
